package com.translator;

import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Copies the settings that the original Translator plugin stored under {@code translator.*}
 * into the group used by this plugin. The migration runs once and only replaces values that
 * are still at their default, so a user who already configured the new group keeps it.
 */
@Singleton
class ConfigMigration
{
	private static final Logger log = LoggerFactory.getLogger(ConfigMigration.class);

	static final String LEGACY_GROUP = "translator";
	static final String CONFIG_GROUP = "translator-enhanced";
	static final String MARKER = "migratedFromTranslatorConfig";

	private static final Migration[] MIGRATIONS =
	{
		new Migration("SelectLanguage", "spanish"),
		new Migration("enableOSRSTextCollection", "false"),
		new Migration("translateMenuOptions", "true"),
		// NPC, item and object names stay off by default. They were often enabled in the
		// original plugin, but translating names is confusing during trading and guides.
		new Migration("translateDialogues", "true"),
		new Migration("translateDialogueOptions", "false"),
		new Migration("translateQuestGuide", "true"),
		new Migration("captureInterfaceTexts", "false"),
		new Migration("useLocalCorrections", "true"),
	};

	private final ConfigManager configManager;

	@Inject
	ConfigMigration(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	void migrate()
	{
		if ("true".equals(configManager.getConfiguration(CONFIG_GROUP, MARKER)))
		{
			return;
		}

		int migrated = 0;

		for (Migration migration : MIGRATIONS)
		{
			String legacy = configManager.getConfiguration(LEGACY_GROUP, migration.key);
			if (legacy == null)
			{
				continue;
			}

			String current = configManager.getConfiguration(CONFIG_GROUP, migration.key);
			if (current != null && !current.equalsIgnoreCase(migration.defaultValue))
			{
				continue;
			}

			configManager.setConfiguration(CONFIG_GROUP, migration.key, legacy);
			migrated++;
		}

		configManager.setConfiguration(CONFIG_GROUP, MARKER, "true");
		if (migrated > 0)
		{
			log.debug("migrated {} settings from the legacy translator config", migrated);
		}
	}

	private static final class Migration
	{
		private final String key;
		private final String defaultValue;

		private Migration(String key, String defaultValue)
		{
			this.key = key;
			this.defaultValue = defaultValue;
		}
	}
}

package com.translator;

import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.StandardOpenOption;
import java.util.Queue;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Saves interface texts that have no reviewed translation, so they can be translated and
 * shipped with the plugin.
 *
 * <p>The goal is a curated dictionary instead of machine translation: journal texts contain
 * names of NPCs, monsters and places that must stay in english, which is something an
 * automatic translation can not know.</p>
 *
 * <p>Output: {@code untranslated/<language>.txt} inside the plugin data directory, one
 * {@code english;} line per text, ready to be filled in and merged into
 * {@code src/main/resources/translations/interface/<language>.txt}.</p>
 */
@Singleton
class InterfaceTextCapture
{
	private static final Logger log = LoggerFactory.getLogger(InterfaceTextCapture.class);

	/**
	 * {@code file + \u0000 + text} of everything already written or already present in the file,
	 * so restarting the client does not duplicate the contribution file.
	 */
	private final Set<String> captured = ConcurrentHashMap.newKeySet();

	/**
	 * Texts waiting for the executor. Kept separate from {@link #captured} so a failed write
	 * can be retried and a text cannot be queued twice while it is being flushed.
	 */
	private final Set<String> queued = ConcurrentHashMap.newKeySet();

	private final Queue<PendingCapture> pending = new ConcurrentLinkedQueue<>();

	private final Set<Filepath> loadedFiles = ConcurrentHashMap.newKeySet();

	private final AtomicBoolean flushScheduled = new AtomicBoolean();

	private Filepath directory;

	private ExecutorService executor;

	private boolean writeFailed;

	@Inject
	InterfaceTextCapture()
	{
	}

	void setDirectory(Filepath directory)
	{
		this.directory = directory;
	}

	void setExecutor(ExecutorService executor)
	{
		this.executor = executor;
		if (executor != null && !pending.isEmpty())
		{
			scheduleFlush();
		}
	}

	/**
	 * Queues a text to be appended to the contribution file. This runs on the client thread,
	 * so it must never touch the filesystem.
	 *
	 * @param language target language this text would be translated to
	 * @param text     english text as it appears in game
	 */
	void capture(TranslatorConfig.Language language, String text)
	{
		if (directory == null || text == null || text.isEmpty())
		{
			return;
		}

		Filepath file = directory.join("untranslated").join(language + ".txt");
		String key = file + "\u0000" + text;

		if (captured.contains(key) || !queued.add(key))
		{
			return;
		}

		pending.add(new PendingCapture(file, text, key));
		scheduleFlush();
	}

	private void scheduleFlush()
	{
		ExecutorService current = executor;
		if (current == null || !flushScheduled.compareAndSet(false, true))
		{
			return;
		}

		try
		{
			current.execute(this::flush);
		}
		catch (RejectedExecutionException e)
		{
			flushScheduled.set(false);
		}
	}

	private void flush()
	{
		try
		{
			PendingCapture capture;
			while ((capture = pending.poll()) != null)
			{
				loadExistingKeys(capture.file);

				if (captured.contains(capture.key))
				{
					queued.remove(capture.key);
					continue;
				}

				try
				{
					capture.file.getParent().createDirectories();
					capture.file.write(capture.text + ";\n",
						StandardOpenOption.CREATE, StandardOpenOption.APPEND);
					captured.add(capture.key);
					queued.remove(capture.key);
				}
				catch (IOException e)
				{
					queued.remove(capture.key);
					if (!writeFailed)
					{
						writeFailed = true;
						log.warn("failed to write untranslated interface texts to {}",
							capture.file, e);
					}
				}
			}
		}
		finally
		{
			flushScheduled.set(false);
			if (!pending.isEmpty())
			{
				scheduleFlush();
			}
		}
	}

	/**
	 * Reads the keys already present so they are not written again.
	 */
	private void loadExistingKeys(Filepath file)
	{
		if (!loadedFiles.add(file) || !file.isFile())
		{
			return;
		}

		try (BufferedReader reader = file.openBufferedReader())
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.charAt(0) == '#')
				{
					continue;
				}

				int separator = line.indexOf(';');
				String key = separator >= 0 ? line.substring(0, separator) : line;
				if (!key.isEmpty())
				{
					captured.add(file + "\u0000" + key);
				}
			}
		}
		catch (IOException e)
		{
			log.debug("failed to read existing untranslated texts from {}", file, e);
		}
	}

	private static final class PendingCapture
	{
		private final Filepath file;
		private final String text;
		private final String key;

		private PendingCapture(Filepath file, String text, String key)
		{
			this.file = file;
			this.text = text;
			this.key = key;
		}
	}
}

package com.translator;

import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

import javax.inject.Inject;
import java.util.IdentityHashMap;
import java.util.Map;

/**
 * Translates right click menu entries.
 *
 * <p>Two independent things can be translated, each with its own toggle:</p>
 * <ul>
 *   <li>the option (verb): {@code Talk-to} -&gt; {@code Hablar con}</li>
 *   <li>the target (name): {@code Goblin} -&gt; {@code Duende}</li>
 * </ul>
 *
 * <p>Entries are only modified right before the menu is rendered, never when they are added.
 * Other plugins (Menu Entry Swapper is the classic example) decide what to swap and in which
 * order by reading the option and target text, so translating earlier makes their text
 * matching fail and the menu ends up in the wrong order.</p>
 *
 * <p>Names are resolved against the downloaded dictionaries by their english name, never by
 * id: the dictionaries are indexed by name.</p>
 */
class MenuEntryTranslator
{
	/**
	 * Interface groups whose menu entries are item ops even when the client does not report an
	 * item id (worn equipment).
	 */
	private static final int EQUIPMENT_GROUP = InterfaceID.Equipment.UNIVERSE >>> 16;
	private static final int EQUIPMENT_SIDE_GROUP = InterfaceID.EquipmentSide.ITEMS >>> 16;

	private final TranslatorConfig config;
	private final TranslationStore store;
	private final TranslatorAPI api;

	/**
	 * Cached result of {@link TranslationSettings#anyMenuTranslationEnabled()}, updated on
	 * configuration changes, so the hot path (every menu entry of every frame) is a single
	 * field read when menus are not translated at all.
	 */
	private volatile boolean enabled;

	/**
	 * Text this plugin already applied to each entry, by object identity.
	 *
	 * <p>The menu is not rebuilt on every frame, so the same {@link MenuEntry} objects are
	 * rendered again and again. Without this, a translated text would be translated a second
	 * time on the next frame and, because a few upstream entries are indexed by an already
	 * translated string, {@code Use} turned into {@code Usar} and then into {@code usar}.</p>
	 */
	private Map<MenuEntry, String[]> appliedTexts = new IdentityHashMap<>();

	@Inject
	MenuEntryTranslator(TranslatorConfig config, TranslationStore store, TranslatorAPI api)
	{
		this.config = config;
		this.store = store;
		this.api = api;
	}

	void setEnabled(boolean enabled)
	{
		this.enabled = enabled;
	}

	/**
	 * Forgets what was applied, eg. after a language change or a reload.
	 */
	void reset()
	{
		appliedTexts.clear();
	}

	// Other plugins match English options on click.
	void restoreMenuOption(MenuOptionClicked event)
	{
		if (!config.translateMenuOptions())
		{
			return;
		}

		MenuEntry entry = event.getMenuEntry();
		if (entry == null)
		{
			return;
		}

		String option = entry.getOption();
		String original = option == null
			? null
			: store.lookupOriginal(TranslationType.MENU_OPTION, option);
		if (original != null && !original.equals(option))
		{
			entry.setOption(original);
		}
	}

	/**
	 * Translates every entry of the menu about to be rendered, at most once per entry state.
	 */
	void translateMenu(MenuEntry[] entries)
	{
		if (!enabled || entries == null || entries.length == 0)
		{
			if (!appliedTexts.isEmpty())
			{
				appliedTexts.clear();
			}
			return;
		}

		Map<MenuEntry, String[]> previous = appliedTexts;
		Map<MenuEntry, String[]> current = new IdentityHashMap<>(entries.length);

		for (MenuEntry entry : entries)
		{
			if (entry == null)
			{
				continue;
			}

			String option = entry.getOption();
			String target = entry.getTarget();
			String[] applied = previous.get(entry);

			// translate only when the entry is new or its text changed since we touched it
			if (applied == null || !equals(applied[0], option) || !equals(applied[1], target))
			{
				translateOption(entry);
				translateTarget(entry);
			}

			current.put(entry, new String[]{entry.getOption(), entry.getTarget()});
		}

		// replacing the map also drops entries that are no longer in the menu
		appliedTexts = current;
	}

	private static boolean equals(String a, String b)
	{
		return a == null ? b == null : a.equals(b);
	}

	/**
	 * Queues the english option for the opt-in data collection. Called when the entry is
	 * added, so the collected text is always the untranslated one.
	 */
	void collect(MenuEntry entry)
	{
		if (entry == null || !config.enableTextCapture())
		{
			return;
		}

		String option = entry.getOption();
		if (option != null && !option.isEmpty())
		{
			api.collect(TranslationType.MENU_OPTION, option);
		}
	}

	private void translateOption(MenuEntry entry)
	{
		if (!config.translateMenuOptions())
		{
			return;
		}

		String option = entry.getOption();
		if (option == null || option.isEmpty())
		{
			return;
		}

		String translated = store.lookup(TranslationType.MENU_OPTION, option);
		if (translated == null || translated.equals(option))
		{
			return;
		}

		entry.setOption(translated);
	}

	private void translateTarget(MenuEntry entry)
	{
		TranslationType type = typeFor(entry);
		if (type == null || !isEnabled(type))
		{
			return;
		}

		MenuTarget target = MenuTarget.parse(entry.getTarget());
		if (target == null)
		{
			return;
		}

		// always try the full name first: "Clue scroll (easy)" is a name, not a suffix
		String translated = lookup(type, target.getName());
		if (translated != null && !translated.equals(target.getName()))
		{
			entry.setTarget(target.withName(translated));
			return;
		}

		// fall back to the name without its "(2)" / "(level-2)" suffix
		String core = target.getCoreName();
		if (core == null)
		{
			return;
		}

		translated = lookup(type, core);
		if (translated == null || translated.equals(core))
		{
			return;
		}

		entry.setTarget(target.withName(translated + target.getCoreSuffix()));
	}

	/**
	 * Resolves a name, falling back to the sibling dictionary: a few item ops are reported as
	 * object ops and vice versa.
	 */
	private String lookup(TranslationType type, String name)
	{
		String translated = store.lookup(type, name);
		if (translated != null)
		{
			return translated;
		}

		TranslationType alternative = type == TranslationType.ITEM ? TranslationType.OBJECT
			: type == TranslationType.OBJECT ? TranslationType.ITEM
			: null;

		return alternative == null || !isEnabled(alternative) ? null : store.lookup(alternative, name);
	}

	/**
	 * Classifies an entry to know which dictionary to use. Returns {@code null} for entries
	 * that do not have a translatable target (players, widgets, RuneLite's own entries...).
	 */
	private static TranslationType typeFor(MenuEntry entry)
	{
		if (entry.getNpc() != null)
		{
			return TranslationType.NPC;
		}

		// player names must never be translated
		if (entry.getPlayer() != null)
		{
			return null;
		}

		if (entry.getItemId() > 0)
		{
			return TranslationType.ITEM;
		}

		MenuAction action = entry.getType();
		if (isGroundItemAction(action))
		{
			return TranslationType.ITEM;
		}

		Widget widget = entry.getWidget();
		if (widget != null)
		{
			// worn equipment: item ops on a widget, often without an item id
			return isEquipmentWidget(widget.getId()) ? TranslationType.ITEM : null;
		}

		if (isIgnoredAction(action))
		{
			return null;
		}

		return entry.getIdentifier() > 0 ? TranslationType.OBJECT : null;
	}

	private static boolean isEquipmentWidget(int widgetId)
	{
		int group = widgetId >>> 16;
		return group == EQUIPMENT_GROUP || group == EQUIPMENT_SIDE_GROUP;
	}

	private static boolean isGroundItemAction(MenuAction action)
	{
		if (action == null)
		{
			return false;
		}

		switch (action)
		{
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
			case ITEM_USE_ON_GROUND_ITEM:
			case WIDGET_TARGET_ON_GROUND_ITEM:
			case EXAMINE_ITEM_GROUND:
				return true;
			default:
				return false;
		}
	}

	/**
	 * Actions whose identifier is not a game object id.
	 */
	private static boolean isIgnoredAction(MenuAction action)
	{
		if (action == null)
		{
			return true;
		}

		switch (action)
		{
			case WALK:
			case CC_OP:
			case CC_OP_LOW_PRIORITY:
			case RUNELITE:
			case RUNELITE_HIGH_PRIORITY:
			case RUNELITE_LOW_PRIORITY:
			case RUNELITE_WIDGET:
			case RUNELITE_OVERLAY:
			case RUNELITE_OVERLAY_CONFIG:
			case RUNELITE_PLAYER:
			case RUNELITE_INFOBOX:
				return true;
			default:
				return false;
		}
	}

	private boolean isEnabled(TranslationType type)
	{
		switch (type)
		{
			case NPC:
				return config.translateNpcNames();
			case ITEM:
				return config.translateItemNames();
			case OBJECT:
				return config.translateObjectNames();
			default:
				return false;
		}
	}
}

package com.translator;

/**
 * A parsed right click menu target.
 *
 * <p>OSRS builds menu targets out of optional colour tags plus the entity name, and sometimes
 * a suffix:</p>
 *
 * <pre>
 *   &lt;col=ffff00&gt;Goblin&lt;col=ff0000&gt; (level-2)&lt;/col&gt;   NPC with combat level
 *   &lt;col=00ffff&gt;Tree&lt;/col&gt;                            game object
 *   Shark (2)                                             stacked ground item
 *   Prayer potion(4)                                      item whose name contains parentheses
 * </pre>
 *
 * <p>Splitting it into prefix (colour tags), name and suffix (combat level, amount and colour
 * tags) allows translating only the name while preserving everything else byte for byte.</p>
 */
final class MenuTarget
{
	private final String prefix;
	private final String name;
	private final String suffix;

	private MenuTarget(String prefix, String name, String suffix)
	{
		this.prefix = prefix;
		this.name = name;
		this.suffix = suffix;
	}

	/**
	 * Parses a raw menu target.
	 *
	 * @param raw the raw target as returned by {@link net.runelite.api.MenuEntry#getTarget()}
	 * @return the parsed target, or {@code null} when there is nothing translatable
	 */
	static MenuTarget parse(String raw)
	{
		if (raw == null || raw.isEmpty())
		{
			return null;
		}

		// skip leading colour tags, eg. "<col=ffff00>"
		int start = 0;
		while (start < raw.length() && raw.charAt(start) == '<')
		{
			int close = raw.indexOf('>', start);
			if (close < 0)
			{
				start = 0;
				break;
			}
			start = close + 1;
		}

		if (start >= raw.length())
		{
			return null;
		}

		// the name ends at the next tag (combat level / closing colour)
		int end = raw.indexOf('<', start);
		if (end < 0)
		{
			end = raw.length();
		}

		if (end <= start)
		{
			return null;
		}

		String name = raw.substring(start, end);
		if (name.trim().isEmpty())
		{
			return null;
		}

		return new MenuTarget(raw.substring(0, start), name, raw.substring(end));
	}

	/**
	 * @return the untranslated entity name, without colour tags.
	 */
	String getName()
	{
		return name;
	}

	/**
	 * Some targets have a suffix that is not part of the name, eg. {@code "Shark (2)"} or
	 * {@code "Goblin (level-2)"}. Only the part before it has to be translated.
	 *
	 * <p>Note that the suffix is only used as a fallback: many names legitimately contain
	 * parentheses ({@code Clue scroll (easy)}), so the full name is always tried first.</p>
	 *
	 * @return the name without the trailing {@code " (...)"} group, or {@code null} if there
	 * is no such group
	 */
	String getCoreName()
	{
		int suffixStart = coreSuffixStart();
		return suffixStart > 0 ? name.substring(0, suffixStart) : null;
	}

	/**
	 * @return the trailing {@code " (...)"} group, or {@code null} if there is none
	 */
	String getCoreSuffix()
	{
		int suffixStart = coreSuffixStart();
		return suffixStart > 0 ? name.substring(suffixStart) : null;
	}

	private int coreSuffixStart()
	{
		int suffixStart = name.indexOf(" (");
		return suffixStart > 0 ? suffixStart : -1;
	}

	/**
	 * Rebuilds the target with the name replaced.
	 *
	 * @param translated the translated name
	 * @return the full target, keeping colour tags, combat level and amount untouched
	 */
	String withName(String translated)
	{
		return prefix + translated + suffix;
	}
}

package com.translator;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;

/**
 * Translates the user configuration into decisions the rest of the plugin can use.
 *
 * <p>Keeping this mapping in one place means a new toggle only has to be wired here, and the
 * loaders (which dictionaries to download) and the translators (which entries to touch) can
 * never disagree.</p>
 */
@Singleton
class TranslationSettings
{
	private final TranslatorConfig config;

	@Inject
	TranslationSettings(TranslatorConfig config)
	{
		this.config = config;
	}

	/**
	 * @return whether the given dictionary is needed by at least one enabled feature
	 */
	boolean isEnabled(TranslationType type)
	{
		switch (type)
		{
			case DIALOGUE:
				return config.translateDialogues() || config.translateDialogueOptions();
			case NPC:
				return config.translateNpcNames();
			case ITEM:
				return config.translateItemNames();
			case OBJECT:
				return config.translateObjectNames();
			case MENU_OPTION:
				return config.translateMenuOptions();
			case INTERFACE:
				return config.translateQuestGuide();
			default:
				return false;
		}
	}

	List<TranslationType> enabledTypes()
	{
		List<TranslationType> types = new ArrayList<>(TranslationType.values().length);
		for (TranslationType type : TranslationType.values())
		{
			if (isEnabled(type))
			{
				types.add(type);
			}
		}
		return types;
	}

	/**
	 * @return whether anything inside right click menus should be translated
	 */
	boolean anyMenuTranslationEnabled()
	{
		return config.translateMenuOptions()
			|| config.translateNpcNames()
			|| config.translateItemNames()
			|| config.translateObjectNames();
	}
}

package com.translator;

import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Holds the loaded dictionaries and resolves {@code english -> translation}.
 *
 * <p>Dictionaries are downloaded lazily (only the ones the user enabled) and stored as
 * immutable maps, so the client thread can read them while a background thread reloads them.
 * A reload never mutates a map that is being read; it swaps the whole reference instead.</p>
 *
 * <p>Corrections are applied on top of the downloaded data in this order:</p>
 * <ol>
 *   <li>dictionaries from {@code github.com/iolave/osrs-translations} or the curated
 *       translation repository</li>
 *   <li>corrections bundled with the plugin ({@code /translations/overrides/<lang>.txt})</li>
 *   <li>the user's own corrections ({@code ~/.runelite/plugin-data/translator-enhanced/overrides/<lang>.txt})</li>
 * </ol>
 */
@Singleton
class TranslationStore
{
	private static final Logger log = LoggerFactory.getLogger(TranslationStore.class);

	private static final String BUNDLED_OVERRIDES = "/translations/overrides/%s.txt";
	private static final String BUNDLED_INTERFACE = "/translations/interface/%s.txt";
	private static final String BUNDLED_MENU_OPTION = "/translations/menu_entry_option_fallback/%s.txt";
	private static final String PATTERN_PREFIX = "re:";

	/**
	 * Start of the requirement annotation in a diary task, eg.
	 * {@code Catch a Mackerel at Catherby.<col=ffffff>(<col=800000>16 Fishing...}.
	 */
	private static final String ANNOTATION_PREFIX = "<col=ffffff>(";

	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	private static final Pattern WHITESPACE = Pattern.compile("\\s+");

	private final TranslatorAPI api;
	private final TranslatorConfig config;

	private Filepath directory;

	private final Map<TranslationType, Map<String, String>> dictionaries = new ConcurrentHashMap<>();

	/**
	 * Entries prefixed with {@code re:} in the translation files, applied to texts that have no
	 * exact match. Needed for strings with numbers: {@code <col=800000>Combat Level 10<br>}.
	 */
	private final Map<TranslationType, List<PatternTranslation>> patterns = new ConcurrentHashMap<>();

	/**
	 * Translation to original text, used to recover the english text of a widget that was
	 * already translated by a previous session or plugin version.
	 */
	private final Map<TranslationType, Map<String, String>> reverse = new ConcurrentHashMap<>();

	/**
	 * Keys and values compared without tags or spaces, used when the exact text does not match.
	 * The game moves {@code <br>} around when a line is re-rendered, so the same task can arrive
	 * with or without the break.
	 */
	private final Map<TranslationType, Map<String, String>> signatures = new ConcurrentHashMap<>();

	private final Map<TranslationType, Map<String, String>> annotated = new ConcurrentHashMap<>();

	private final Map<TranslationType, Map<String, String>> annotatedSignatures = new ConcurrentHashMap<>();

	/**
	 * Language the loaded dictionaries belong to. Bumped on every language change so a slow
	 * download of the previous language can not overwrite the new one.
	 */
	private volatile TranslatorConfig.Language language;

	/**
	 * Incremented whenever the dictionaries are invalidated, so a download that finishes
	 * after a language change or a reload is discarded instead of published.
	 */
	private final AtomicInteger generation = new AtomicInteger();

	@Inject
	TranslationStore(TranslatorAPI api, TranslatorConfig config)
	{
		this.api = api;
		this.config = config;
	}

	void setLanguage(TranslatorConfig.Language language)
	{
		this.language = language;
		generation.incrementAndGet();
		dictionaries.clear();
		patterns.clear();
		reverse.clear();
		signatures.clear();
		annotated.clear();
		annotatedSignatures.clear();
	}

	void setDirectory(Filepath directory)
	{
		this.directory = directory;
	}

	boolean isLoaded(TranslationType type)
	{
		return dictionaries.containsKey(type);
	}

	/**
	 * Forgets every dictionary so the next {@link #load(TranslationType)} downloads them again.
	 */
	void clear()
	{
		generation.incrementAndGet();
		dictionaries.clear();
		patterns.clear();
		reverse.clear();
		signatures.clear();
		annotated.clear();
		annotatedSignatures.clear();
	}

	/**
	 * Downloads one dictionary, applies the corrections and publishes it.
	 *
	 * @throws IOException when the download fails
	 */
	void load(TranslationType type) throws IOException
	{
		TranslatorConfig.Language language = this.language;
		int generation = this.generation.get();

		Map<String, String> merged;
		int downloaded;
		Filepath cache = cachePath(type, language);

		if (type.isCurated())
		{
			merged = new HashMap<>();
			if (type.isBundled())
			{
				String resource = type == TranslationType.MENU_OPTION
					? BUNDLED_MENU_OPTION
					: BUNDLED_INTERFACE;
				readOverrides(
					merged,
					TranslationStore.class.getResourceAsStream(String.format(resource, language)),
					"bundled " + type.fileName() + " " + language);
			}

			boolean online = type == TranslationType.MENU_OPTION
				? config.useOnlineMenuTranslations()
				: config.useOnlineInterfaceTranslations();
			if (online)
			{
				try
				{
					merged.putAll(api.downloadCurated(type, language, cache));
				}
				catch (IOException e)
				{
					log.debug("failed to download {} translations, using the cached copy",
						type.fileName(), e);
					readCache(cache, merged);
				}
			}
			else
			{
				readCache(cache, merged);
			}

			downloaded = merged.size();
		}
		else
		{
			try
			{
				merged = new HashMap<>(api.download(type, language));
				writeCache(cache, merged);
			}
			catch (IOException e)
			{
				merged = new HashMap<>();
				readCache(cache, merged);
				if (merged.isEmpty())
				{
					throw e;
				}
			}
			downloaded = merged.size();
		}

		int overrides = applyOverrides(merged, language);
		addTrimmedAliases(merged);
		addAnnotationAliases(merged);
		addColourCloseAliases(merged);
		List<PatternTranslation> compiled = extractPatterns(merged, type);

		if (generation != this.generation.get())
		{
			log.debug("discarding {} translations for {}: the language changed while loading",
				downloaded, type.fileName());
			return;
		}

		dictionaries.put(type, Collections.unmodifiableMap(merged));
		patterns.put(type, compiled);
		reverse.put(type, buildReverse(merged));
		signatures.put(type, buildSignatures(merged));
		annotated.put(type, buildAnnotated(merged));
		annotatedSignatures.put(type, buildAnnotatedSignatures(merged));
		log.info("loaded {} translations for {}/{} ({} corrections applied, {} patterns)",
			downloaded, language, type.fileName(), overrides, compiled.size());
	}

	/**
	 * Resolves a text.
	 *
	 * @param type dictionary to use
	 * @param text english text, as it appears in game
	 * @return the translation, or {@code null} when the dictionary has no entry for it
	 */
	String lookup(TranslationType type, String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}

		Map<String, String> dictionary = dictionaries.get(type);
		if (dictionary == null)
		{
			return null;
		}

		String translated = dictionary.get(text);
		if (translated == null)
		{
			// some downloads contain names with leading/trailing spaces
			String trimmed = text.trim();
			if (!trimmed.equals(text))
			{
				translated = dictionary.get(trimmed);
			}
		}

		if (translated != null)
		{
			return translated;
		}

		Map<String, String> index = signatures.get(type);
		translated = index == null ? null : index.get(signature(text));
		if (translated != null)
		{
			return translated;
		}

		return applyPatterns(patterns.get(type), text);
	}

	/**
	 * Applies the {@code re:} entries, in file order. A text can match several patterns, eg. a
	 * single widget with several level requirements.
	 *
	 * @return the translated text, or {@code null} when nothing matched
	 */
	static String applyPatterns(List<PatternTranslation> patterns, String text)
	{
		if (patterns == null || patterns.isEmpty() || text == null)
		{
			return null;
		}

		String result = text;
		boolean changed = false;

		for (PatternTranslation pattern : patterns)
		{
			String applied = pattern.apply(result);
			if (applied != null)
			{
				result = applied;
				changed = true;
			}
		}

		return changed && !result.equals(text) ? result : null;
	}

	/**
	 * Removes the {@code re:} entries from a dictionary and compiles them.
	 */
	private static List<PatternTranslation> extractPatterns(Map<String, String> dictionary, TranslationType type)
	{
		List<PatternTranslation> compiled = new ArrayList<>();

		Iterator<Map.Entry<String, String>> iterator = dictionary.entrySet().iterator();
		while (iterator.hasNext())
		{
			Map.Entry<String, String> entry = iterator.next();
			if (!entry.getKey().startsWith(PATTERN_PREFIX))
			{
				continue;
			}

			iterator.remove();

			try
			{
				compiled.add(new PatternTranslation(
					entry.getKey().substring(PATTERN_PREFIX.length()),
					entry.getValue()));
			}
			catch (PatternSyntaxException e)
			{
				log.warn("invalid {} pattern in {}: {}", PATTERN_PREFIX, type.fileName(), entry.getKey(), e);
			}
		}

		return compiled;
	}

	/**
	 * A regex translation. The replacement can use {@code $1}, {@code $2}... to keep the
	 * dynamic parts (numbers, levels) of the original text.
	 */
	static final class PatternTranslation
	{
		private final Pattern pattern;
		private final String replacement;

		PatternTranslation(String regex, String replacement)
		{
			this.pattern = Pattern.compile(regex);
			this.replacement = replacement;
		}

		String apply(String text)
		{
			Matcher matcher = pattern.matcher(text);
			return matcher.find() ? matcher.replaceAll(replacement) : null;
		}
	}

	private Filepath cachePath(TranslationType type, TranslatorConfig.Language language)
	{
		return directory == null ? null : directory.join(type.fileName()).join(language + ".txt");
	}

	private static void readCache(Filepath file, Map<String, String> dictionary)
	{
		if (file == null || !file.isFile())
		{
			return;
		}

		try (InputStream in = file.openInputStream();
			 Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			dictionary.putAll(parse(reader));
		}
		catch (IOException e)
		{
			log.debug("failed to read cached translations from {}", file, e);
		}
	}

	private static void writeCache(Filepath file, Map<String, String> entries)
	{
		if (file == null)
		{
			return;
		}

		StringBuilder builder = new StringBuilder();
		entries.forEach((key, value) -> builder.append(key).append(';').append(value).append('\n'));

		try
		{
			file.getParent().createDirectories();
			Filepath temporary = file.getParent().createTempFile("translations-", ".tmp");
			try
			{
				temporary.write(builder.toString());
				temporary.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
			finally
			{
				temporary.deleteIfExists();
			}
		}
		catch (IOException e)
		{
			log.debug("failed to cache translations at {}", file, e);
		}
	}

	private int applyOverrides(Map<String, String> dictionary, TranslatorConfig.Language language)
	{
		if (!config.useLocalCorrections())
		{
			return 0;
		}

		int applied = readOverrides(
			dictionary,
			TranslationStore.class.getResourceAsStream(String.format(BUNDLED_OVERRIDES, language)),
			"bundled " + language);

		Filepath userFile = directory == null ? null : directory.join("overrides").join(language + ".txt");
		if (userFile != null && userFile.isFile())
		{
			try (InputStream in = userFile.openInputStream())
			{
				applied += readOverrides(dictionary, in, userFile.toString());
			}
			catch (IOException e)
			{
				log.warn("failed to read user corrections from {}", userFile, e);
			}
		}

		return applied;
	}

	private static int readOverrides(Map<String, String> dictionary, InputStream in, String source)
	{
		if (in == null)
		{
			return 0;
		}

		try (InputStream stream = in;
			 Reader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			Map<String, String> corrections = parse(reader);
			dictionary.putAll(corrections);
			log.debug("applied {} corrections from {}", corrections.size(), source);
			return corrections.size();
		}
		catch (IOException e)
		{
			log.warn("failed to read corrections from {}", source, e);
			return 0;
		}
	}

	/**
	 * Adds aliases so a name can be found with or without surrounding spaces: a few upstream
	 * entries are stored with a leading space ({@code " Sneaky undead fowl"}).
	 */
	static void addTrimmedAliases(Map<String, String> dictionary)
	{
		Map<String, String> aliases = new HashMap<>();
		for (Map.Entry<String, String> entry : dictionary.entrySet())
		{
			String key = entry.getKey();
			String trimmed = key.trim();
			if (!trimmed.equals(key) && !dictionary.containsKey(trimmed))
			{
				aliases.put(trimmed, entry.getValue());
			}
		}
		dictionary.putAll(aliases);
	}

	/**
	 * Adds the variant without the requirement annotation.
	 *
	 * <p>A diary task appears twice in game: with its requirements in the detail view
	 * ({@code Catch a Mackerel...<col=ffffff>(<col=800000>16 Fishing...}) and without them in the
	 * list. Both must resolve to the same translation.</p>
	 */
	static void addAnnotationAliases(Map<String, String> dictionary)
	{
		Map<String, String> aliases = new HashMap<>();

		for (Map.Entry<String, String> entry : dictionary.entrySet())
		{
			String key = entry.getKey();
			int annotation = key.indexOf(ANNOTATION_PREFIX);
			if (annotation <= 0)
			{
				continue;
			}

			String bareKey = key.substring(0, annotation);
			if (bareKey.isEmpty())
			{
				continue;
			}

			String value = entry.getValue();
			int valueAnnotation = value.indexOf(ANNOTATION_PREFIX);
			String bareValue = valueAnnotation >= 0 ? value.substring(0, valueAnnotation) : value;

			if (!dictionary.containsKey(bareKey) && !bareValue.trim().isEmpty())
			{
				aliases.put(bareKey, bareValue);
			}
		}

		dictionary.putAll(aliases);
	}

	/**
	 * Finds the english text a translation came from.
	 *
	 * <p>Needed for widgets that already contain a translation, eg. because the plugin was
	 * updated while the interface was open: the stored text is not a key, so a normal lookup
	 * would miss it and the panel would keep an outdated translation.</p>
	 *
	 * @return the original text, or {@code null} when the text is not a known translation
	 */
	String lookupOriginal(TranslationType type, String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}

		Map<String, String> map = reverse.get(type);
		if (map == null)
		{
			return null;
		}

		String original = map.get(text);
		if (original == null)
		{
			original = map.get(withoutBreaks(text));
		}
		if (original == null)
		{
			original = map.get(signature(text));
		}
		return original;
	}

	/** @return the translation of a bare task that includes its requirements, or {@code null} */
	String lookupAnnotated(TranslationType type, String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}

		Map<String, String> map = annotated.get(type);
		String value = map == null ? null : map.get(text);
		if (value != null)
		{
			return value;
		}

		Map<String, String> bySignature = annotatedSignatures.get(type);
		return bySignature == null ? null : bySignature.get(signature(text));
	}

	/**
	 * @return the text without line breaks or tags, used as a last resort when comparing
	 */
	static String signature(String text)
	{
		return WHITESPACE.matcher(TAG.matcher(text).replaceAll("")).replaceAll("");
	}

	/**
	 * @return the text with the line breaks this plugin inserts replaced by spaces
	 */
	static String withoutBreaks(String text)
	{
		return text.replace("<br>", " ").replaceAll("\\s{2,}", " ").trim();
	}

	static Map<String, String> buildReverse(Map<String, String> dictionary)
	{
		Map<String, String> reversed = new HashMap<>();

		for (Map.Entry<String, String> entry : dictionary.entrySet())
		{
			String key = entry.getKey();
			if (key.startsWith(PATTERN_PREFIX))
			{
				continue;
			}

			String value = entry.getValue();
			if (value != null && !value.isEmpty() && !value.equals(key))
			{
				reversed.putIfAbsent(value, key);
			}
		}

		for (Map.Entry<String, String> entry : dictionary.entrySet())
		{
			String key = entry.getKey();
			String value = entry.getValue();
			if (!key.startsWith(PATTERN_PREFIX) && value != null && !value.isEmpty())
			{
				reversed.putIfAbsent(signature(value), key);
			}
		}

		return reversed;
	}

	private static Map<String, String> buildSignatures(Map<String, String> dictionary)
	{
		Map<String, String> index = new HashMap<>();

		for (Map.Entry<String, String> entry : dictionary.entrySet())
		{
			if (!entry.getKey().startsWith(PATTERN_PREFIX) && entry.getValue() != null)
			{
				index.putIfAbsent(signature(entry.getKey()), entry.getValue());
			}
		}

		return index;
	}

	static Map<String, String> buildAnnotated(Map<String, String> dictionary)
	{
		Map<String, String> index = new HashMap<>();

		for (Map.Entry<String, String> entry : dictionary.entrySet())
		{
			String key = entry.getKey();
			int annotation = key.indexOf(ANNOTATION_PREFIX);

			if (annotation > 0 && entry.getValue() != null)
			{
				index.putIfAbsent(key.substring(0, annotation), entry.getValue());
			}
		}

		return index;
	}

	static Map<String, String> buildAnnotatedSignatures(Map<String, String> dictionary)
	{
		Map<String, String> index = new HashMap<>();

		for (Map.Entry<String, String> entry : dictionary.entrySet())
		{
			String key = entry.getKey();
			int annotation = key.indexOf(ANNOTATION_PREFIX);

			if (annotation > 0 && entry.getValue() != null)
			{
				index.putIfAbsent(signature(key.substring(0, annotation)), entry.getValue());
			}
		}

		return index;
	}

	/**
	 * Adds the variant with a trailing {@code </col>}.
	 *
	 * <p>Some interface texts end with {@code </col>} and others do not, depending on the
	 * widget. The same translation has to answer for both.</p>
	 */
	static void addColourCloseAliases(Map<String, String> dictionary)
	{
		Map<String, String> aliases = new HashMap<>();

		for (Map.Entry<String, String> entry : dictionary.entrySet())
		{
			String key = entry.getKey();
			String value = entry.getValue();

			if (key.startsWith(PATTERN_PREFIX)
				|| key.contains("</col>") || value == null || !value.contains("<col="))
			{
				continue;
			}

			aliases.put(key + "</col>", value + "</col>");
		}

		dictionary.putAll(aliases);
	}

	/**
	 * Parses a translation file.
	 *
	 * <p>The format is {@code original;translation}, one per line. Everything after the first
	 * {@code ;} is the translation, because translations themselves may contain semicolons
	 * (614 dialogue lines in the Spanish file do). Lines starting with {@code #} and empty lines
	 * are ignored. Keys are not trimmed on purpose: a few names in the upstream files have a
	 * meaningful leading space.</p>
	 *
	 * @param reader the file contents
	 * @return a mutable map of {@code english -> translation}
	 */
	static Map<String, String> parse(Reader reader) throws IOException
	{
		Map<String, String> dictionary = new HashMap<>();
		BufferedReader bufferedReader = new BufferedReader(reader);
		String line;
		while ((line = bufferedReader.readLine()) != null)
		{
			if (line.isEmpty() || line.charAt(0) == '#')
			{
				continue;
			}

			int separator = line.indexOf(';');
			if (separator <= 0 || separator >= line.length() - 1)
			{
				continue;
			}

			dictionary.put(line.substring(0, separator), line.substring(separator + 1));
		}

		return dictionary;
	}
}

package com.translator;

/**
 * The translation dictionaries the plugin can load.
 *
 * <p>The file name is also the value used by the data collection endpoint, so it must not be
 * renamed.</p>
 */
public enum TranslationType
{
	/** Chatbox dialogues (NPC / player lines). */
	DIALOGUE("dialogue", false, false),
	/** NPC names, eg. {@code Goblin}. */
	NPC("npc", false, false),
	/** Item names, eg. {@code Abyssal whip}. */
	ITEM("item", false, false),
	/** Game object names, eg. {@code Tree}. */
	OBJECT("object", false, false),
	/** Right click menu options, eg. {@code Talk-to}. */
	MENU_OPTION("menu_entry_option", true, true),
	/** Interface texts (quest journals, achievement diaries, combat achievements). */
	INTERFACE("interface", true, true);

	private final String fileName;
	private final boolean bundled;
	private final boolean curated;

	TranslationType(String fileName, boolean bundled, boolean curated)
	{
		this.fileName = fileName;
		this.bundled = bundled;
		this.curated = curated;
	}

	/**
	 * @return the file name used both by the download URL and the collection API.
	 */
	public String fileName()
	{
		return fileName;
	}

	public boolean isBundled()
	{
		return bundled;
	}

	public boolean isCurated()
	{
		return curated;
	}
}

